package deploy

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"
	"text/tabwriter"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"gopkg.in/yaml.v3"
)

// Show reports what the GitOps repository declares: the registry, the ArgoCD
// location, the platform, the environments in promotion order, every onboarded
// system and component, and the secret-bearing resources their manifests name.
//
// It reads git and nothing else — no kustomize build, no ArgoCD call. A local
// render is not what ArgoCD applies, and an answer that is not the truth is
// worse than none; secrets are therefore found by walking the kustomize inputs
// (base/ and every overlays/<env>/ directory) rather than any rendered output.
//
// It writes nothing, and exit is 0 even when part of the tree is broken: a
// component whose component.yaml does not load is reported inline, not treated
// as fatal. This command reports; it does not gate.
func Show(ctx context.Context, opts ShowOptions) error {
	opts.applyDefaults()
	out := opts.output()

	// No kustomize: this renders nothing, and demanding a binary it never runs
	// would be a prerequisite for no reason.
	s, err := openSession(ctx, opts.session(), "git")
	if err != nil {
		return err
	}
	defer s.Close()
	repo, deployCfg := s.repo, s.deployCfg

	res := ShowResult{
		Repository: RepositoryInfo{URL: repo.URL},
		Registry:   deployCfg.Registry,
		Argocd: ArgocdInfo{
			Server:       deployCfg.Argocd.Server,
			AppNamespace: deployCfg.Argocd.AppNamespace,
		},
		Platform: PlatformInfo{
			Provider:    deployCfg.Platform.Provider,
			Pubsub:      deployCfg.Platform.Pubsub,
			SecretStore: deployCfg.Platform.SecretStore,
		},
	}

	if head, err := repo.Git.HEAD(ctx); err == nil {
		res.Repository.Revision = head
		fmt.Fprintf(opts.Stderr, "refreshed %s at %s\n", repo.URL, git.ShortSHA(head))
	}

	for _, env := range deployCfg.PromotionOrder() {
		cfg := deployCfg.Environments[env]
		res.Environments = append(res.Environments, EnvironmentInfo{
			Name:                 env,
			Sync:                 cfg.Sync,
			PromotesFrom:         cfg.PromotesFrom,
			RequireSourceHealthy: cfg.RequireSourceHealthy,
			Scratch:              cfg.Scratch,
		})
	}

	res.Systems = showSystems(repo.Root, opts.Stderr)

	return reportShow(out, res)
}

// showSystems groups every component in the repository by system and reads
// what each declares. A component whose component.yaml fails to load or
// validate is reported with Error set — it must not fail the whole listing, so
// the kind and environment list fall back to what the tree itself says.
func showSystems(root string, stderr io.Writer) []SystemInfo {
	var systems []SystemInfo
	byKey := map[string]int{}

	for _, coord := range gitops.ListComponents(root) {
		info := ComponentInfo{
			Name:   coord.Component,
			Kind:   gitops.KindService,
			Images: []string{},
		}

		comp, err := gitops.LoadComponentConfig(componentDir(root, coord))
		if err != nil {
			info.Error = firstLine(err.Error())
		} else {
			info.Kind = componentKind(comp)
			info.Environments = comp.Environments
			for _, img := range comp.Images {
				info.Images = append(info.Images, img.Name)
			}
		}

		// Secrets are scanned from the tree even when component.yaml did not
		// load: what is checked in is a fact regardless of the component's own
		// bookkeeping, and a half-onboarded component is exactly what this
		// command exists to surface.
		info.Secrets = scanComponentSecrets(root, coord, stderr)

		key := coord.Domain + "/" + coord.System
		i, ok := byKey[key]
		if !ok {
			systems = append(systems, SystemInfo{Domain: coord.Domain, System: coord.System, Components: []ComponentInfo{}})
			i = len(systems) - 1
			byKey[key] = i
		}
		systems[i].Components = append(systems[i].Components, info)
	}
	return systems
}

// secretDocument is the minimum of a manifest the scanner needs: enough to
// name a secret-bearing resource, with every other field ignored.
type secretDocument struct {
	Kind     string `yaml:"kind"`
	Metadata struct {
		Name string `yaml:"name"`
	} `yaml:"metadata"`
}

// secretKinds are the resource kinds that carry or reference secret material.
var secretKinds = map[string]bool{
	"Secret":         true,
	"ExternalSecret": true,
	"SealedSecret":   true,
}

// scanComponentSecrets walks a component's kustomize inputs — base/ and every
// directory that exists under overlays/ — and names the secret-bearing
// resources in them.
//
// Every overlay directory is scanned, declared or not: an overlay nobody
// declared is exactly the half-onboarded state this command exists to surface.
// Nothing is rendered, so the same resource seen in base/ and patched in an
// overlay is reported once per location — this reports files, not patch
// semantics. A malformed document is skipped with a diagnostic naming the
// file: this is a scanner, not a validator.
func scanComponentSecrets(root string, coord gitops.Coordinate, stderr io.Writer) []SecretRef {
	rel := coord.RelPath()
	dirs := []string{path.Join(rel, "base")}

	overlaysDir := gitops.JoinRel(root, path.Join(rel, gitops.OverlaysDirName))
	if entries, err := os.ReadDir(overlaysDir); err == nil {
		for _, e := range entries {
			if e.IsDir() {
				dirs = append(dirs, path.Join(rel, gitops.OverlaysDirName, e.Name()))
			}
		}
	}

	var out []SecretRef
	for _, dir := range dirs {
		entries, err := os.ReadDir(gitops.JoinRel(root, dir))
		if err != nil {
			continue
		}
		slices.SortFunc(entries, func(a, b os.DirEntry) int { return strings.Compare(a.Name(), b.Name()) })
		for _, e := range entries {
			name := e.Name()
			if e.IsDir() || !(strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".yml")) {
				continue
			}
			file := path.Join(dir, name)
			if name == "kustomization.yaml" || name == "kustomization.yml" {
				out = append(out, scanKustomizationSecrets(root, coord, file, stderr)...)
				continue
			}
			out = append(out, scanManifestSecrets(root, coord, file, stderr)...)
		}
	}
	return out
}

// scanManifestSecrets reads one manifest file and names every Secret,
// ExternalSecret and SealedSecret document in it.
func scanManifestSecrets(root string, coord gitops.Coordinate, file string, stderr io.Writer) []SecretRef {
	f, err := os.Open(gitops.JoinRel(root, file))
	if err != nil {
		fmt.Fprintf(stderr, "note: skipping %s: %v\n", file, err)
		return nil
	}
	defer f.Close()

	var out []SecretRef
	dec := yaml.NewDecoder(f)
	for {
		var doc secretDocument
		err := dec.Decode(&doc)
		if err != nil {
			// The end of the stream is not a malformed document.
			if err == io.EOF {
				break
			}
			fmt.Fprintf(stderr, "note: skipping a malformed document in %s: %v\n", file, err)
			continue
		}
		if doc.Kind == "" {
			continue
		}
		if secretKinds[doc.Kind] {
			out = append(out, SecretRef{
				Kind:      doc.Kind,
				Name:      doc.Metadata.Name,
				Component: coord.String(),
				File:      file,
			})
		}
	}
	return out
}

// kustomizationSecrets is the one kustomize directive that declares secret
// material without naming a resource file.
type kustomizationSecrets struct {
	SecretGenerator []struct {
		Name string `yaml:"name"`
	} `yaml:"secretGenerator"`
}

// scanKustomizationSecrets reads a kustomization.yaml and names each
// secretGenerator entry. The file is a kustomize directive rather than a
// resource document, so it is parsed separately and its entries carry no File.
func scanKustomizationSecrets(root string, coord gitops.Coordinate, file string, stderr io.Writer) []SecretRef {
	data, err := os.ReadFile(gitops.JoinRel(root, file))
	if err != nil {
		fmt.Fprintf(stderr, "note: skipping %s: %v\n", file, err)
		return nil
	}
	var k kustomizationSecrets
	if err := yaml.Unmarshal(data, &k); err != nil {
		fmt.Fprintf(stderr, "note: skipping malformed %s: %v\n", file, err)
		return nil
	}
	var out []SecretRef
	for _, gen := range k.SecretGenerator {
		if gen.Name == "" {
			continue
		}
		out = append(out, SecretRef{
			Kind:      "secretGenerator",
			Name:      gen.Name,
			Component: coord.String(),
		})
	}
	return out
}

// reportShow writes the result, as JSON or as the plain report. Both render
// from the one result, so the two presenters cannot drift.
func reportShow(out output, res ShowResult) error {
	if out.Format == OutputJSON {
		enc := json.NewEncoder(out.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(res); err != nil {
			return fmt.Errorf("write JSON result: %w", err)
		}
		return nil
	}

	w := out.Stdout

	revision := res.Repository.Revision
	if revision != "" {
		revision = " @ " + git.ShortSHA(revision)
	}
	fmt.Fprintf(w, "repository  %s%s\n", res.Repository.URL, revision)
	fmt.Fprintf(w, "registry    %s\n", res.Registry)
	fmt.Fprintf(w, "argocd      %s", res.Argocd.Server)
	if res.Argocd.AppNamespace != "" {
		fmt.Fprintf(w, " (apps in %s)", res.Argocd.AppNamespace)
	}
	fmt.Fprintln(w)
	if platform := platformLine(res.Platform); platform != "" {
		fmt.Fprintf(w, "platform    %s\n", platform)
	}

	fmt.Fprintln(w, "\nENVIRONMENTS")
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "NAME\tSYNC\tPROMOTES FROM\tGATE")
	for _, env := range res.Environments {
		gate := noValue
		if env.RequireSourceHealthy {
			gate = "source healthy"
		}
		fmt.Fprintf(tw, "%s\t%s\t%s\t%s\n", env.Name, env.Sync, orNone(strings.Join(env.PromotesFrom, ", ")), gate)
	}
	if err := tw.Flush(); err != nil {
		return err
	}

	fmt.Fprintln(w, "\nSYSTEMS")
	if len(res.Systems) == 0 {
		fmt.Fprintln(w, "  none onboarded")
	}
	for _, sys := range res.Systems {
		fmt.Fprintf(w, "%s/%s\n", sys.Domain, sys.System)
		ctw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
		for _, comp := range sys.Components {
			if comp.Error != "" {
				fmt.Fprintf(ctw, "  %s\t%s\t%s\n", comp.Name, noValue, "error: "+comp.Error)
				continue
			}
			fmt.Fprintf(ctw, "  %s\t%s\t%s\n", comp.Name, comp.Kind, orNone(strings.Join(comp.Environments, ", ")))
		}
		if err := ctw.Flush(); err != nil {
			return err
		}
	}

	fmt.Fprintln(w, "\nSECRETS")
	if res.Platform.SecretStore != "" {
		fmt.Fprintf(w, "store       %s\n", res.Platform.SecretStore)
	}
	secrets := showSecrets(res)
	if len(secrets) == 0 {
		fmt.Fprintln(w, "none declared")
		return nil
	}
	stw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	fmt.Fprintln(stw, "COMPONENT\tKIND\tNAME\tFILE")
	for _, s := range secrets {
		fmt.Fprintf(stw, "%s\t%s\t%s\t%s\n", s.Component, s.Kind, s.Name, orNone(s.File))
	}
	return stw.Flush()
}

// platformLine renders the platform declaration on one line, omitting what is
// undeclared: an absent value and an empty one are not the same claim.
func platformLine(p PlatformInfo) string {
	var parts []string
	if p.Provider != "" {
		parts = append(parts, "provider "+p.Provider)
	}
	if p.Pubsub != "" {
		parts = append(parts, "pubsub "+p.Pubsub)
	}
	if p.SecretStore != "" {
		parts = append(parts, "secrets "+p.SecretStore)
	}
	return strings.Join(parts, ", ")
}

// showSecrets flattens the systems tree into the secrets list, in tree order.
func showSecrets(res ShowResult) []SecretRef {
	var out []SecretRef
	for _, sys := range res.Systems {
		for _, comp := range sys.Components {
			out = append(out, comp.Secrets...)
		}
	}
	return out
}

// ShowOptions configures Show.
//
// Narrower than every other options type here: there is no Component and no
// Environment, because show is about the whole repository at once — the
// question it answers is what exists, which cannot be asked of a part. There
// is no ArgocdServer either, since nothing here contacts ArgoCD.
type ShowOptions struct {
	GitopsRepo   string
	OutputFormat string
	CacheRoot    string

	Runner    command.Runner
	UserAgent string
	Stdout    io.Writer
	Stderr    io.Writer
}

func (o ShowOptions) output() output {
	return output{Format: o.OutputFormat, Stdout: o.Stdout, Stderr: o.Stderr}
}

func (o ShowOptions) session() sessionOptions {
	return sessionOptions{
		GitopsRepo: o.GitopsRepo,
		CacheRoot:  o.CacheRoot,
		Runner:     o.Runner,
		Stderr:     o.Stderr,
	}
}

func (o *ShowOptions) applyDefaults() {
	if o.Runner == nil {
		o.Runner = git.DefaultRunner()
	}
	if o.OutputFormat == "" {
		o.OutputFormat = OutputPlain
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
}

// componentDir is where a coordinate's component.yaml, base/ and overlays/
// live.
func componentDir(root string, coord gitops.Coordinate) string {
	return filepath.Join(root, filepath.FromSlash(coord.RelPath()))
}

