package main

import (
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"github.com/spf13/cobra"
)

type showFlags struct {
	gitopsRepo string
	output     string
}

var showFlagValues = showFlags{output: deploy.OutputPlain}

var deployShowCmd = &cobra.Command{
	Use:   "show",
	Short: "Show what the GitOps repository declares",
	Long: "Report the GitOps repository's declared state: the registry, the ArgoCD server and application " +
		"namespace, the platform (provider, pub/sub, secret store), the environments in promotion order with " +
		"their sync policies, every onboarded system and component, and the secret-bearing resources their " +
		"manifests name — Secret, ExternalSecret, SealedSecret, and secretGenerator entries.\n\n" +
		"Everything comes from a refreshed checkout of the repository: deploy.yaml, each component.yaml, and " +
		"the YAML under every component's base/ and overlays/ directories. Nothing is rendered and ArgoCD is " +
		"never contacted. Secrets are reported by name, kind and owning component, and are never decrypted " +
		"or read for values.\n\n" +
		"Nothing is written, and the exit code is 0 even when part of the tree is broken: a component whose " +
		"component.yaml cannot be read is reported inline rather than failing the listing. The command fails " +
		"only when the repository cannot be resolved or refreshed, or deploy.yaml is missing or invalid.",
	Args: cobra.NoArgs,
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(showFlagValues.output, deploy.OutputPlain, deploy.OutputJSON); err != nil {
			return err
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		return deploy.Show(ctx, deploy.ShowOptions{
			GitopsRepo:   showFlagValues.gitopsRepo,
			OutputFormat: showFlagValues.output,
			UserAgent:    "intropy-cli/" + version,
			Stdout:       cmd.OutOrStdout(),
			Stderr:       cmd.ErrOrStderr(),
		})
	},
}

func init() {
	f := deployShowCmd.Flags()
	f.StringVar(&showFlagValues.gitopsRepo, "gitops-repo", "", flagUsageGitopsRepo)
	f.StringVarP(&showFlagValues.output, "output", "o", deploy.OutputPlain, flagUsageOutput)

	// Deliberately no --env, --domain or --system: show is the whole
	// repository, and narrowing is what the component commands are for. No
	// --argocd-server either, because nothing here contacts ArgoCD.

	deployCmd.AddCommand(deployShowCmd)
}

