package dashboard

import (
	"context"
	"encoding/json"
	"net/http"
	"sync"
	"testing"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
)

// stubShow is a ShowResult shaped like a healthy repository: two systems, one
// shared component owning a secret, and the promotion pipeline in order.
func stubShow() *deploy.ShowResult {
	return &deploy.ShowResult{
		Repository: deploy.RepositoryInfo{
			URL:      "git@example.com:acme/gitops.git",
			Revision: "a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2",
		},
		Registry: "harbor.intropy.io",
		Argocd:   deploy.ArgocdInfo{Server: "argocd.intropy.io", AppNamespace: "customer-fluxia"},
		Platform: deploy.PlatformInfo{Provider: "azure", Pubsub: "rabbitmq", SecretStore: "azure.keyvault"},
		Environments: []deploy.EnvironmentInfo{
			{Name: "dev", Sync: "auto"},
			{Name: "staging", Sync: "auto", PromotesFrom: []string{"dev"}},
			{Name: "prod", Sync: "manual", PromotesFrom: []string{"staging"}, RequireSourceHealthy: true},
		},
		Systems: []deploy.SystemInfo{{
			Domain: "orders",
			System: "order-flow",
			Components: []deploy.ComponentInfo{
				{Name: "order-extractor", Kind: "service", Images: []string{"harbor.intropy.io/integrations/order-extractor"}, Environments: []string{"dev", "staging", "prod"}},
				{Name: "order-flow-shared", Kind: "shared", Environments: []string{"dev", "staging", "prod"},
					Secrets: []deploy.SecretRef{{Kind: "Secret", Name: "rabbitmq-credentials", Component: "orders/order-flow/order-flow-shared", File: "domains/orders/order-flow/order-flow-shared/base/secret.yaml"}}},
			},
		}},
	}
}

func gitopsJSON(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200: %s", rec.Code, rec.Body.String())
	}
	var body map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	return body
}

// The endpoint's whole job is to hand the command's own result through without
// editing it, so the view and the terminal cannot draw different conclusions
// from the same checkout.
func TestGitopsCarriesTheCommandResultThrough(t *testing.T) {
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		gitops: func(context.Context) gitopsState {
			return gitopsState{Show: stubShow(), ReadAt: time.Now()}
		},
	})

	body := gitopsJSON(t, get(t, h, "/api/gitops"))
	show, ok := body["show"].(map[string]any)
	if !ok {
		t.Fatalf("show missing from payload: %v", body)
	}
	if show["registry"] != "harbor.intropy.io" {
		t.Errorf("registry = %v, want the command's value", show["registry"])
	}
	envs, ok := show["environments"].([]any)
	if !ok || len(envs) != 3 {
		t.Fatalf("environments = %v, want the three in promotion order", show["environments"])
	}
	if envs[2].(map[string]any)["name"] != "prod" {
		t.Errorf("last environment = %v, want prod: promotion order is the pipeline's story", envs[2])
	}
	if body["readAt"] == nil {
		t.Error("readAt should be served so a reader can tell how current this is")
	}
	if _, present := body["error"]; present {
		t.Errorf("a successful read should carry no error: %v", body["error"])
	}
}

// An unconfigured repository, a held checkout lock and a missing deploy.yaml
// are all statements about the lookup, and the command already words each of
// them well. Rewriting one here would risk turning "we could not find out"
// into "nothing is declared".
func TestGitopsServesTheCommandErrorVerbatim(t *testing.T) {
	const msg = "no GitOps repository configured; pass --gitops-repo, set INTROPY_GITOPS_REPO, or add gitopsRepo to /home/x/.config/intropy/config.yaml"
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		gitops: func(context.Context) gitopsState {
			return gitopsState{Error: msg, ReadAt: time.Now()}
		},
	})

	body := gitopsJSON(t, get(t, h, "/api/gitops"))
	if body["error"] != msg {
		t.Errorf("error = %q, want the command's message unchanged:\n%q", body["error"], msg)
	}
	if _, present := body["show"]; present {
		t.Error("an error must not come with a result: an empty view reads as 'nothing declared'")
	}
}

// Running the command refreshes a GitOps checkout under an exclusive lock, so a
// GET must not pay for it more than once. A POST is how you ask for a fresh
// read — after a deployment landed from another terminal, say.
func TestGitopsCachedUntilRefresh(t *testing.T) {
	calls := 0
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		gitops: func(context.Context) gitopsState {
			calls++
			return gitopsState{Show: stubShow()}
		},
	})

	get(t, h, "/api/gitops")
	get(t, h, "/api/gitops")
	if calls != 1 {
		t.Fatalf("provider calls after two GETs = %d, want 1", calls)
	}
	post(t, h, "/api/gitops/refresh")
	if calls != 2 {
		t.Fatalf("provider calls after POST = %d, want 2", calls)
	}
	get(t, h, "/api/gitops")
	if calls != 2 {
		t.Fatalf("provider calls after post-refresh GET = %d, want 2", calls)
	}
}

// The command holds the checkout lock for its whole run, so the handler
// serialises concurrent requests rather than letting them contend over it.
func TestGitopsSerialisesConcurrentReads(t *testing.T) {
	var mu sync.Mutex
	inFlight, overlapped := 0, false
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		gitops: func(context.Context) gitopsState {
			mu.Lock()
			inFlight++
			if inFlight > 1 {
				overlapped = true
			}
			mu.Unlock()

			time.Sleep(20 * time.Millisecond)

			mu.Lock()
			inFlight--
			mu.Unlock()
			return gitopsState{Show: stubShow()}
		},
	})

	var wg sync.WaitGroup
	for range 3 {
		wg.Go(func() { get(t, h, "/api/gitops") })
	}
	wg.Wait()

	mu.Lock()
	defer mu.Unlock()
	if overlapped {
		t.Error("two reads ran at once; they would contend over the GitOps checkout lock")
	}
}

// The warm-up is the sidebar load's promise to the GitOps view: the checkout
// refresh runs in the background once, so the first view does not block on it.
func TestGitopsWarmsOnceFromTheSidebarLoad(t *testing.T) {
	done := make(chan struct{})
	var mu sync.Mutex
	calls := 0
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		gitops: func(context.Context) gitopsState {
			mu.Lock()
			calls++
			mu.Unlock()
			close(done)
			return gitopsState{Show: stubShow()}
		},
	})

	get(t, h, "/api/integrations")
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("listing integrations should warm the GitOps cache in the background")
	}

	// A second sidebar load must not stack another read on a warm cache.
	get(t, h, "/api/integrations")
	// The warm answer is what the GitOps endpoint then serves, without paying
	// for the command again.
	get(t, h, "/api/gitops")
	mu.Lock()
	defer mu.Unlock()
	if calls != 1 {
		t.Errorf("provider calls = %d, want 1: the warm-up and the endpoint share one read", calls)
	}
}

