//go:build integration

package deploy

import (
	"bytes"
	"context"
	"encoding/json"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/gitops/gitopstest"
	"github.com/integrio-intropy/intropy-cli/internal/gittest"
)

// newShowFixture builds a GitOps origin with one healthy service component,
// one broken one, and one shared component owning secrets — the three shapes
// show must report side by side.
func newShowFixture(t *testing.T) (origin, cacheRoot string) {
	t.Helper()
	origin = gitopstest.NewRepo(t, gitopstest.Component{
		Coordinate:   "orders/order-flow/order-extractor",
		Environments: []string{"dev", "staging", "prod"},
	})
	commit := func(rel, content, msg string) {
		gittest.WriteFile(t, filepath.Join(origin, filepath.FromSlash(rel)), content)
		gittest.Run(t, origin, "add", ".")
		gittest.Run(t, origin, "commit", "--quiet", "-m", msg)
	}

	// A component whose component.yaml does not validate: reported inline,
	// never fatal to the listing.
	commit("domains/orders/order-flow/broken/component.yaml",
		"schemaVersion: 1\nimages:\n  - name: harbor.intropy.io/integrations/broken\nenvironments: [dev]\n",
		"onboard a broken component")
	commit("domains/orders/order-flow/broken/base/kustomization.yaml",
		"apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\n",
		"give the broken component a base")

	// A shared component holding the system's secrets.
	shared := "domains/orders/order-flow/order-flow-shared"
	commit(shared+"/component.yaml",
		"schemaVersion: 1\nname: order-flow-shared\nkind: shared\nenvironments: [dev, staging, prod]\n",
		"onboard the shared component")
	commit(shared+"/base/kustomization.yaml",
		"apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\nresources:\n  - secret.yaml\nsecretGenerator:\n  - name: app-secret\n    literals:\n      - TOKEN=placeholder\n",
		"declare the secret generator")
	commit(shared+"/base/secret.yaml",
		"apiVersion: v1\nkind: Secret\nmetadata:\n  name: rabbitmq-credentials\nstringData:\n  password: not-read\n",
		"add the credentials secret")
	commit(shared+"/base/multi.yaml",
		"apiVersion: external-secrets.io/v1beta1\nkind: ExternalSecret\nmetadata:\n  name: kv-sync\n---\nkind: Secret\n  metadata: [this is not a mapping\n",
		"add an external secret with a malformed sibling document")
	// An overlay nobody declared: scanned for secrets anyway, because the
	// half-onboarded state is what this command exists to surface.
	commit(shared+"/overlays/nobody/kustomization.yaml",
		"apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\nresources:\n  - sealed.yaml\n",
		"start an undeclared overlay")
	commit(shared+"/overlays/nobody/sealed.yaml",
		"apiVersion: bitnami.com/v1alpha1\nkind: SealedSecret\nmetadata:\n  name: db-password\n",
		"add a sealed secret to the undeclared overlay")

	cfgHome := t.TempDir()
	t.Setenv("XDG_CONFIG_HOME", cfgHome)
	t.Setenv("INTROPY_GITOPS_REPO", "")
	gittest.WriteFile(t, filepath.Join(cfgHome, "intropy", "config.yaml"), "gitopsRepo: "+origin+"\n")

	return origin, t.TempDir()
}

func showJSON(t *testing.T, cacheRoot string) (ShowResult, string) {
	t.Helper()
	var stdout, stderr bytes.Buffer
	if err := Show(context.Background(), ShowOptions{
		CacheRoot:    cacheRoot,
		OutputFormat: OutputJSON,
		Stdout:       &stdout,
		Stderr:       &stderr,
	}); err != nil {
		t.Fatalf("Show() = %v", err)
	}
	var res ShowResult
	if err := json.Unmarshal(stdout.Bytes(), &res); err != nil {
		t.Fatalf("stdout is not valid JSON: %v\n%s", err, stdout.String())
	}
	return res, stderr.String()
}

func componentByName(t *testing.T, res ShowResult, name string) ComponentInfo {
	t.Helper()
	for _, sys := range res.Systems {
		for _, comp := range sys.Components {
			if comp.Name == name {
				return comp
			}
		}
	}
	t.Fatalf("component %q not in the result: %+v", name, res.Systems)
	return ComponentInfo{}
}

// The whole point of the ordering: dev, staging, prod tells the pipeline's
// story; alphabetical order would put prod in the middle of it.
func TestShowReportsEnvironmentsInPromotionOrder(t *testing.T) {
	_, cacheRoot := newShowFixture(t)
	res, _ := showJSON(t, cacheRoot)

	var names []string
	for _, env := range res.Environments {
		names = append(names, env.Name)
	}
	if want := []string{"dev", "staging", "prod"}; !equalStrings(names, want) {
		t.Errorf("environments = %v, want promotion order %v", names, want)
	}
	if res.Environments[2].Sync != "manual" || !res.Environments[2].RequireSourceHealthy {
		t.Errorf("prod should carry its manual sync gate: %+v", res.Environments[2])
	}
	if got := res.Environments[1].PromotesFrom; len(got) != 1 || got[0] != "dev" {
		t.Errorf("staging.PromotesFrom = %v, want [dev]", got)
	}
}

// The header facts map straight off deploy.yaml and the refreshed checkout —
// including the full revision, which the JSON contract carries and plain
// output shortens.
func TestShowReportsTheRepositoryHeader(t *testing.T) {
	origin, cacheRoot := newShowFixture(t)
	res, stderr := showJSON(t, cacheRoot)

	head := gittest.Run(t, origin, "rev-parse", "main")
	if res.Repository.Revision != head {
		t.Errorf("revision = %q, want the checkout's HEAD %q", res.Repository.Revision, head)
	}
	if res.Registry != "harbor.intropy.io" {
		t.Errorf("registry = %q", res.Registry)
	}
	if res.Argocd.Server != "argocd.intropy.io" || res.Argocd.AppNamespace != "customer-fluxia" {
		t.Errorf("argocd = %+v", res.Argocd)
	}
	if !strings.Contains(stderr, "refreshed") || !strings.Contains(stderr, head[:7]) {
		t.Errorf("stderr should name the revision the refresh landed on:\n%s", stderr)
	}
}

// A component whose component.yaml does not validate is reported with Error
// set — a fact worth seeing, and no reason to withhold the rest of the tree.
func TestShowReportsABrokenComponentInline(t *testing.T) {
	_, cacheRoot := newShowFixture(t)
	res, _ := showJSON(t, cacheRoot)

	broken := componentByName(t, res, "broken")
	if broken.Error == "" {
		t.Errorf("broken component should carry its error: %+v", broken)
	}
	healthy := componentByName(t, res, "order-extractor")
	if healthy.Error != "" || len(healthy.Environments) != 3 {
		t.Errorf("the healthy component should still be listed in full: %+v", healthy)
	}
	if healthy.Kind != "service" || len(healthy.Images) != 1 {
		t.Errorf("kind and images should come from component.yaml: %+v", healthy)
	}
}

// The scanner's job end to end: a Secret, an ExternalSecret and a
// secretGenerator detected, the malformed sibling document skipped with a
// diagnostic, and the undeclared overlay's SealedSecret found anyway.
func TestShowScansComponentSecrets(t *testing.T) {
	_, cacheRoot := newShowFixture(t)
	res, stderr := showJSON(t, cacheRoot)

	shared := componentByName(t, res, "order-flow-shared")
	byName := map[string]string{}
	for _, s := range shared.Secrets {
		byName[s.Name] = s.Kind
	}
	want := map[string]string{
		"rabbitmq-credentials": "Secret",
		"kv-sync":              "ExternalSecret",
		"app-secret":           "secretGenerator",
		"db-password":          "SealedSecret",
	}
	if len(byName) != len(want) {
		t.Errorf("secrets = %v, want %v", byName, want)
	}
	for name, kind := range want {
		if byName[name] != kind {
			t.Errorf("secret %q has kind %q, want %q (all: %v)", name, byName[name], kind, byName)
		}
	}
	for _, s := range shared.Secrets {
		if s.Component != "orders/order-flow/order-flow-shared" {
			t.Errorf("secret %q should name its owning coordinate, got %q", s.Name, s.Component)
		}
		if s.Kind == "secretGenerator" && s.File != "" {
			t.Errorf("a secretGenerator carries no file: %+v", s)
		}
	}
	if !strings.Contains(stderr, "multi.yaml") {
		t.Errorf("stderr should name the file with the malformed document:\n%s", stderr)
	}
}

// A read-only command must leave the repository exactly as it found it.
func TestShowWritesNothing(t *testing.T) {
	origin, cacheRoot := newShowFixture(t)

	before := gittest.Run(t, origin, "rev-parse", "main")
	showJSON(t, cacheRoot)
	if after := gittest.Run(t, origin, "rev-parse", "main"); after != before {
		t.Errorf("the GitOps branch moved: %s → %s", before, after)
	}
}

// The plain output is the same result rendered for a terminal: pipeline in
// promotion order, systems grouped, secrets named.
func TestShowPlainOutputCarriesTheSameFacts(t *testing.T) {
	_, cacheRoot := newShowFixture(t)

	var stdout, stderr bytes.Buffer
	if err := Show(context.Background(), ShowOptions{
		CacheRoot: cacheRoot,
		Stdout:    &stdout,
		Stderr:    &stderr,
	}); err != nil {
		t.Fatalf("Show() = %v", err)
	}
	out := stdout.String()

	dev, staging, prod := strings.Index(out, "dev"), strings.Index(out, "staging"), strings.Index(out, "prod")
	if !(dev < staging && staging < prod) {
		t.Errorf("environments should read dev, staging, prod:\n%s", out)
	}
	for _, want := range []string{"harbor.intropy.io", "order-extractor", "order-flow-shared", "rabbitmq-credentials", "db-password"} {
		if !strings.Contains(out, want) {
			t.Errorf("output should name %q:\n%s", want, out)
		}
	}
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

package main

import (
	"bytes"
	"errors"
	"strings"
	"testing"
)

func resetShowState(t *testing.T, stdout, stderr *bytes.Buffer) {
	t.Helper()
	resetRootIO(t, stdout, stderr)
	showFlagValues = showFlags{output: "plain"}
	t.Cleanup(func() { showFlagValues = showFlags{output: "plain"} })
}

func runShow(t *testing.T, args ...string) (stdout, stderr *bytes.Buffer, err error) {
	t.Helper()
	stdout, stderr = &bytes.Buffer{}, &bytes.Buffer{}
	resetShowState(t, stdout, stderr)
	rootCmd.SetArgs(append([]string{"deploy", "show"}, args...))
	return stdout, stderr, rootCmd.Execute()
}

func TestShowRejectsUnknownOutputFormat(t *testing.T) {
	_, _, err := runShow(t, "--output", "yaml")
	if err == nil {
		t.Fatal("expected an error for an unsupported output format")
	}
	var ue *usageError
	if !errors.As(err, &ue) {
		t.Errorf("error %q should be a usageError", err)
	}
}

// Show is the whole repository at once. Component filters would suggest it can
// be narrowed, and an ArgoCD address would suggest it contacts the cluster —
// it does neither.
func TestShowHasNoComponentEnvOrArgocdFlags(t *testing.T) {
	for _, name := range []string{"env", "domain", "system", "argocd-server", "no-wait", "timeout", "plan"} {
		if deployShowCmd.Flags().Lookup(name) != nil {
			t.Errorf("show must not define --%s: it reports the whole repository and never contacts ArgoCD", name)
		}
	}
}

func TestShowTakesNoArguments(t *testing.T) {
	_, _, err := runShow(t, "order-extractor")
	if err == nil {
		t.Fatal("expected an error when a positional argument is given")
	}
	if code := exitCode(err); code != 2 {
		t.Errorf("exit code = %d, want 2 for a usage error", code)
	}
}

func TestShowDoesNotShadowRootPersistentPreRun(t *testing.T) {
	if deployShowCmd.PersistentPreRunE != nil || deployShowCmd.PersistentPreRun != nil {
		t.Error("show must not define PersistentPreRunE; it would shadow the root's and break -C")
	}
}

func TestShowIsRegisteredUnderDeploy(t *testing.T) {
	for _, c := range deployCmd.Commands() {
		if c.Name() == "show" {
			return
		}
	}
	t.Error("show is not registered under deploy")
}

func TestShowSubcommandWinsOverTheComponentArgument(t *testing.T) {
	args := []string{"deploy", "show"}

	cmd, _, err := rootCmd.Find(args)
	if err != nil {
		t.Fatalf("deploy show does not resolve: %v", err)
	}
	if cmd != deployShowCmd {
		t.Errorf("resolved to %q, want the show command", cmd.CommandPath())
	}
}

// deploy is not runnable, so a component called show deploys via
// 'deploy pin show' like any other. The parent's help lists show as a
// subcommand.
func TestDeployHelpNamesShowAsSubcommand(t *testing.T) {
	if !strings.Contains(deployCmd.Long, "show") {
		t.Error("deploy's Long should name show among its subcommands")
	}
}

