// secretKinds are the resource kinds that carry or reference secret material.
var secretKinds = map[string]bool{
	"Secret":         true,
	"ExternalSecret": true,
	"SealedSecret":   true,
}

// componentScan is what one component's manifests declare: every resource,
// the secret-bearing ones among them, and the secrets they reference.
type componentScan struct {
	resources []ResourceRef
	secrets   []SecretRef
	refs      []SecretReference
}

// scanComponentManifests walks a component's kustomize inputs — base/ and
// every directory that exists under overlays/ — and inventories what is in
// them.
//
// Every overlay directory is scanned, declared or not: an overlay nobody
// declared is exactly the half-onboarded state this command exists to surface.
// Nothing is rendered, so the same resource seen in base/ and patched in an
// overlay is reported once per location — this reports files, not patch
// semantics. A malformed document is skipped with a diagnostic naming the
// file: this is a scanner, not a validator.
func scanComponentManifests(root string, coord gitops.Coordinate, stderr io.Writer) componentScan {
	rel := coord.RelPath()
	dirs := []string{path.Join(rel, "base")}

	overlaysDir := gitops.JoinRel(root, path.Join(rel, gitops.OverlaysDirName))
	if entries, err := os.ReadDir(overlaysDir); err == nil {
		for _, e := range entries {
			if e.IsDir() {
				dirs = append(dirs, path.Join(rel, gitops.OverlaysDirName, e.Name()))
			}
		}
	}

	var scan componentScan
	for _, dir := range dirs {
		entries, err := os.ReadDir(gitops.JoinRel(root, dir))
		if err != nil {
			continue
		}
		slices.SortFunc(entries, func(a, b os.DirEntry) int { return strings.Compare(a.Name(), b.Name()) })
		for _, e := range entries {
			name := e.Name()
			if e.IsDir() || !(strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".yml")) {
				continue
			}
			file := path.Join(dir, name)
			if name == "kustomization.yaml" || name == "kustomization.yml" {
				scan.secrets = append(scan.secrets, scanKustomizationSecrets(root, coord, file, stderr)...)
				continue
			}
			resources, secrets, refs := scanManifest(root, coord, file, stderr)
			scan.resources = append(scan.resources, resources...)
			scan.secrets = append(scan.secrets, secrets...)
			scan.refs = append(scan.refs, refs...)
		}
	}
	return scan
}

// scanManifest reads one manifest file and inventories it: every resource
// document, the secret-bearing ones among them, and every secret reference
// the documents make.
func scanManifest(root string, coord gitops.Coordinate, file string, stderr io.Writer) (resources []ResourceRef, secrets []SecretRef, refs []SecretReference) {
	data, err := os.ReadFile(gitops.JoinRel(root, file))
	if err != nil {
		fmt.Fprintf(stderr, "note: skipping %s: %v\n", file, err)
		return nil, nil, nil
	}

	for _, chunk := range splitYAMLDocuments(data) {
		var node yaml.Node
		if err := yaml.Unmarshal(chunk, &node); err != nil {
			fmt.Fprintf(stderr, "note: skipping a malformed document in %s: %v\n", file, err)
			continue
		}
		id := resourceIdentity(&node)
		if id.kind == "" {
			continue
		}
		resources = append(resources, ResourceRef{APIVersion: id.apiVersion, Kind: id.kind, Name: id.name, File: file})
		if secretKinds[id.kind] {
			secrets = append(secrets, SecretRef{
				Kind:      id.kind,
				Name:      id.name,
				Component: coord.String(),
				File:      file,
			})
		}

		// A component can consume a secret it does not own — a binding's
		// credentials, a provisioned-elsewhere connection string — and owning
		// and referencing are different claims a reader must not conflate.
		resource := id.kind + " " + id.name
		seen := map[string]bool{}
		for _, name := range secretKeyRefs(&node) {
			if seen[name] {
				// Several keys of one secret (accessKey, secretKey) are one
				// reference, not one per key.
				continue
			}
			seen[name] = true
			refs = append(refs, SecretReference{Name: name, Resource: resource, File: file})
		}
	}
	return resources, secrets, refs
}

// identity is the apiVersion/kind/name triple that names a resource, the same
// identity kustomize.Identities renders for a rendered stream.
type identity struct {
	apiVersion, kind, name string
}

// resourceIdentity reads a document's identity from its YAML node. An empty
// kind marks a document that is not a resource (a comment-only chunk), which
// the scanner skips.
func resourceIdentity(node *yaml.Node) identity {
	root := node
	if root.Kind == yaml.DocumentNode && len(root.Content) > 0 {
		root = root.Content[0]
	}
	metadata := yamlMappingNode(root, "metadata")
	return identity{
		apiVersion: yamlMappingValue(root, "apiVersion"),
		kind:       yamlMappingValue(root, "kind"),
		name:       yamlMappingValue(metadata, "name"),
	}
}

// secretKeyRefs walks a document for every secretKeyRef it contains and
// returns the referenced secret names, in order of appearance. The walk is
// structural rather than schema-aware — container env, Dapr Component
// metadata and volumes all spell the reference the same way, and a scanner
// that knows where each kind keeps its secrets would be one schema per kind.
func secretKeyRefs(node *yaml.Node) []string {
	var out []string
	var walk func(n *yaml.Node)
	walk = func(n *yaml.Node) {
		if n == nil {
			return
		}
		if n.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(n.Content); i += 2 {
				if n.Content[i].Value == "secretKeyRef" {
					if name := yamlMappingValue(n.Content[i+1], "name"); name != "" {
						out = append(out, name)
					}
				}
			}
		}
		for _, child := range n.Content {
			walk(child)
		}
	}
	walk(node)
	return out
}

// yamlMappingNode returns the value mapped to key, or nil.
func yamlMappingNode(node *yaml.Node, key string) *yaml.Node {
	if node == nil || node.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(node.Content); i += 2 {
		if node.Content[i].Value == key {
			return node.Content[i+1]
		}
	}
	return nil
}

// yamlMappingValue returns the scalar mapped to key, or "".
func yamlMappingValue(node *yaml.Node, key string) string {
	if v := yamlMappingNode(node, key); v != nil && v.Kind == yaml.ScalarNode {
		return v.Value
	}
	return ""
}

