			fmt.Fprintf(stw, "%s\t%s\t%s\t%s\n", s.Component, s.Kind, s.Name, orNone(s.File))
		}
		if err := stw.Flush(); err != nil {
			return err
		}
	}
	if len(refs) > 0 {
		// References are secrets the tree consumes without owning; printed
		// under the owned ones rather than merged, because mixing the two
		// would turn a reference into a declaration.
		fmt.Fprintln(w, "references")
		rtw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
		fmt.Fprintln(rtw, "SECRET\tREFERRED BY\tFILE")
		for _, r := range refs {
			fmt.Fprintf(rtw, "%s\t%s\t%s\n", r.Name, r.Resource, orNone(r.File))
		}
		if err := rtw.Flush(); err != nil {
			return err
		}
	}
	return nil
}

// resourceKinds summarises a component's manifest inventory as its unique
// kinds, in order of appearance: "CronJob, Component" says more than a count
// and stays one cell wide.
func resourceKinds(resources []ResourceRef) string {
	seen := map[string]bool{}
	var kinds []string
	for _, r := range resources {
		if !seen[r.Kind] {
			seen[r.Kind] = true
			kinds = append(kinds, r.Kind)
		}
	}
	return orNone(strings.Join(kinds, ", "))
}

// showSecretRefs flattens the systems tree into the secret-reference list,
// in tree order.
func showSecretRefs(res ShowResult) []SecretReference {
	var out []SecretReference
	for _, sys := range res.Systems {
		for _, comp := range sys.Components {
			out = append(out, comp.SecretRefs...)
		}
	}
	return out
}

