	_, cacheRoot := newShowFixture(t)
	res, _ := showJSON(t, cacheRoot)

	extractor := componentByName(t, res, "order-extractor")
	byKind := map[string]string{}
	for _, r := range extractor.Resources {
		byKind[r.Kind] = r.File
	}
	for _, kind := range []string{"Deployment", "Component"} {
		if byKind[kind] == "" {
			t.Errorf("order-extractor should declare a %s, resources: %v", kind, byKind)
		}
	}
	if !strings.HasPrefix(byKind["Component"], "domains/orders/order-flow/order-extractor/") {
		t.Errorf("the Component's file should be repo-relative, got %q", byKind["Component"])
	}

	// The binding consumes order-extractor-s3, which nothing in the tree
	// declares: a reference, not an owned secret.
	if len(extractor.SecretRefs) != 1 || extractor.SecretRefs[0].Name != "order-extractor-s3" {
		t.Errorf("secretRefs = %v, want the binding's reference", extractor.SecretRefs)
	}
	if extractor.SecretRefs[0].Resource != "Component binding.order-source" {
