```go
func literalEnvVar(item *yaml.Node, container string) (envVar, bool) {
    if item.Kind != yaml.MappingNode { return envVar{}, false }
    name := yamlMappingValue(item, "name")
    valueNode := yamlMappingNode(item, "value")
    // valueFrom-backed variables (a secretKeyRef, a fieldRef) are already
    // reported as secret references or are not literal config; the list is
    // for values the repository spells out.
    if name == "" || valueNode == nil || valueNode.Kind != yaml.ScalarNode { return envVar{}, false }
    return envVar{Name: name, Value: valueNode.Value, Container: container}, true
}
