// overlayEnv parses one inline kustomize patch and names the environment
// variables it sets. A patch that does not parse is a diagnostic, like any
// malformed document.
func overlayEnv(patch, file string, stderr io.Writer) []EnvVar {
	var node yaml.Node
	if err := yaml.Unmarshal([]byte(patch), &node); err != nil {
		fmt.Fprintf(stderr, "note: skipping a malformed inline patch in %s: %v\n", file, err)
		return nil
	}
	return envVars(&node, file)
}
