```go
func envVars(node *yaml.Node, file string) []EnvVar {
	var out []EnvVar
	var walk func(n *yaml.Node, container string)
	walk = func(n *yaml.Node, container string) {
		if n == nil { return }
		if n.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(n.Content); i += 2 {
				key, val := n.Content[i], n.Content[i+1]
				switch {
				case key.Value == "env" && val.Kind == yaml.SequenceNode:
					for _, item := range val.Content {
						if ev, ok := literalEnvVar(item, container, file); ok {
							out = append(out, ev)
						}
					}
				case (key.Value == "containers" || key.Value == "initContainers") && val.Kind == yaml.SequenceNode:
					for _, item := range val.Content {
						walk(item, yamlMappingValue(item, "name"))
					}
				default:
					walk(val, container)
				}
			}
			return
		}
		for _, child := range n.Content {
			walk(child, container)
		}
	}
	walk(node, "")
	return out
}

// literalEnvVar reads one env entry. Entries backed by a valueFrom (a
// secretKeyRef, a configMapKeyRef, a fieldRef) are skipped: the secret ones
// are already reported as references, and the rest are not values the
// repository spells out.
func literalEnvVar(item *yaml.Node, container, file string) (EnvVar, bool) {
	if item.Kind != yaml.MappingNode {
		return EnvVar{}, false
	}
	name := yamlMappingValue(item, "name")
	value := yamlMappingNode(item, "value")
	if name == "" || value == nil || value.Kind != yaml.ScalarNode {
		return EnvVar{}, false
	}
	ev := EnvVar{Name: name, Container: container, File: file}
	// Everything in the repository is committed plaintext, so redaction is
	// not a trust boundary — but a well-kept repository holds endpoints here,
	// not passwords, and omitting the password-shaped values is what keeps an
	// accidental one from being rendered.
	if !sensitiveEnvName(name) {
		ev.Value = value.Value
	}
	return ev, true
}

var sensitiveEnvPattern = regexp.MustCompile(`(?i)secret|password|passwd|token|credential|private[-_]?key|api[-_]?key|access[-_]?key|connection[-_]?string`)

func sensitiveEnvName(name string) bool { return sensitiveEnvPattern.MatchString(name) }
