func imagePinSuffix(img OverlayImage) string {
	switch {
	case img.Digest != "":
		return " @ " + shortDigest(img.Digest)
	case img.Tag != "":
		return ":" + img.Tag
	default:
		return ""
	}
}

// envLine renders one variable, truncating long values: an endpoint is
// useful, a pasted JSON blob is not, and the full value is in the JSON.
func envLine(ev EnvVar) string {
	if ev.Value == "" {
		return ev.Name + " (redacted)"
	}
	v := ev.Value
	if len(v) > 72 {
		v = v[:71] + "…"
	}
	return ev.Name + "=" + v
}
