// componentScan is what one component's manifests declare: every resource,
// the secret-bearing ones among them, the secrets they reference, and what
// each overlay sets.
type componentScan struct {
	resources []ResourceRef
	secrets   []SecretRef
	refs      []SecretReference
	overlays  []OverlayInfo
}

// scanComponentManifests walks a component's kustomize inputs — base/ and
// every directory that exists under overlays/ — and inventories what is in
// them.
//
// Every overlay directory is scanned, declared or not: an overlay nobody
// declared is exactly the half-onboarded state this command exists to surface.
// Nothing is rendered, so the same resource seen in base/ and patched in an
// overlay is reported once per location — this reports files, not patch
// semantics. A malformed document is skipped with a diagnostic naming the
// file: this is a scanner, not a validator.
func scanComponentManifests(root string, coord gitops.Coordinate, declaredEnvs []string, stderr io.Writer) componentScan {
	rel := coord.RelPath()

	// The overlay directories are gathered up front: their env patches are
	// deployment configuration no source-derived topology can know, so they
	// are inventoried rather than merely scanned for secrets.
	type overlayDir struct{ name, rel string }
	var overlays []overlayDir
	overlaysDir := gitops.JoinRel(root, path.Join(rel, gitops.OverlaysDirName))
	if entries, err := os.ReadDir(overlaysDir); err == nil {
		for _, e := range entries {
			if e.IsDir() {
				overlays = append(overlays, overlayDir{e.Name(), path.Join(rel, gitops.OverlaysDirName, e.Name())})
			}
		}
	}

	dirs := []string{path.Join(rel, "base")}
	for _, ov := range overlays {
		dirs = append(dirs, ov.rel)
	}

	var scan componentScan
	for _, dir := range dirs {
		entries, err := os.ReadDir(gitops.JoinRel(root, dir))
		if err != nil {
			continue
		}
		slices.SortFunc(entries, func(a, b os.DirEntry) int { return strings.Compare(a.Name(), b.Name()) })
		for _, e := range entries {
			name := e.Name()
			if e.IsDir() || !(strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".yml")) {
				continue
			}
			file := path.Join(dir, name)
			if name == "kustomization.yaml" || name == "kustomization.yml" {
				scan.secrets = append(scan.secrets, scanKustomizationSecrets(root, coord, file, stderr)...)
				continue
			}
			resources, secrets, refs := scanManifest(root, coord, file, stderr)
			scan.resources = append(scan.resources, resources...)
			scan.secrets = append(scan.secrets, secrets...)
			scan.refs = append(scan.refs, refs...)
		}
	}

	for _, ov := range overlays {
		info := scanOverlay(root, ov.name, ov.rel, stderr)
		info.Declared = slices.Contains(declaredEnvs, ov.name)
		scan.overlays = append(scan.overlays, info)
	}
	return scan
}

// kustomizationEnv is the subset of an overlay's kustomization that carries
// deployment configuration worth reporting.
type kustomizationEnv struct {
	Namespace string `yaml:"namespace"`
	Images    []struct {
		Name    string `yaml:"name"`
		NewName string `yaml:"newName"`
		NewTag  string `yaml:"newTag"`
		Digest  string `yaml:"digest"`
	} `yaml:"images"`
	Patches []struct {
		Patch string `yaml:"patch"`
	} `yaml:"patches"`
}

// scanOverlay inventories one overlay directory: the namespace, the pinned
// images, and the literal env values its patches set. An unreadable
// kustomization is reported on the overlay rather than failing the listing.
func scanOverlay(root, name, rel string, stderr io.Writer) OverlayInfo {
	info := OverlayInfo{Name: name}

	file := path.Join(rel, "kustomization.yaml")
	data, err := os.ReadFile(gitops.JoinRel(root, file))
	if err != nil {
		if !os.IsNotExist(err) {
			info.Error = firstLine(err.Error())
		}
		return info
	}
	var k kustomizationEnv
	if err := yaml.Unmarshal(data, &k); err != nil {
		fmt.Fprintf(stderr, "note: skipping malformed %s: %v\n", file, err)
		info.Error = firstLine(err.Error())
		return info
	}

	info.Namespace = k.Namespace
	for _, img := range k.Images {
		name := img.Name
		if img.NewName != "" {
			name = img.NewName
		}
		info.Images = append(info.Images, OverlayImage{Name: name, Digest: img.Digest, Tag: img.NewTag})
	}
	for _, p := range k.Patches {
		info.Env = append(info.Env, overlayPatchEnv(p.Patch)...)
	}
	return info
}

// overlayPatchEnv extracts the literal env values one inline strategic-merge
// patch sets on its target's containers. Only literal `value` entries are
// read: valueFrom goes through a secretKeyRef, which the reference scanner
// already reports without ever touching a value.
func overlayPatchEnv(patch string) []OverlayEnv {
	var node yaml.Node
	if err := yaml.Unmarshal([]byte(patch), &node); err != nil {
		// A patch that does not parse is no worse than the malformed documents
		// the manifest scanner skips, and it is not worth a diagnostic: the
		// overlay's secrets still surface from the file scan.
		return nil
	}
	id := resourceIdentity(&node)
	if id.kind == "" {
		return nil
	}
	workload := id.kind + " " + id.name

	var out []OverlayEnv
	seen := map[string]bool{}
	for _, env := range envEntries(&node) {
		name := yamlMappingValue(env, "name")
		if name == "" || seen[name] {
			continue
		}
		seen[name] = true
		out = append(out, OverlayEnv{Workload: workload, Name: name, Value: redactEnvValue(name, yamlMappingValue(env, "value"))})
	}
	return out
}

// envEntries walks a document for every env entry any container declares:
// the containers[] mapping under containers, initContainers and (for Dapr
// Components) spec.metadata entries, each a list of name/value maps.
func envEntries(node *yaml.Node) []*yaml.Node {
	var out []*yaml.Node
	var walk func(n *yaml.Node)
	walk = func(n *yaml.Node) {
		if n == nil {
			return
		}
		if n.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(n.Content); i += 2 {
				key, val := n.Content[i].Value, n.Content[i+1]
				if (key == "containers" || key == "initContainers") && val.Kind == yaml.SequenceNode {
					for _, container := range val.Content {
						if env := yamlMappingNode(container, "env"); env != nil && env.Kind == yaml.SequenceNode {
							out = append(out, env.Content...)
						}
					}
				}
			}
		}
		for _, child := range n.Content {
			walk(child)
		}
	}
	walk(node)
	return out
}

// credentialName reports whether an env name reads as carrying a credential.
// Anything matching is redacted before it can leave the repository: a CLI
// that prints connection strings into a dashboard is a leak with extra steps.
func credentialName(name string) bool {
	n := strings.ToUpper(name)
	for _, frag := range []string{"SECRET", "PASSWORD", "PASSWD", "TOKEN", "CREDENTIAL", "PRIVATE", "CONN", "APIKEY", "API_KEY", "ACCESS_KEY", "CONNECTIONSTRING"} {
		if strings.Contains(n, frag) {
			return true
		}
	}
	return false
}

// redactEnvValue masks a credential-shaped literal. The redaction marker is
// deliberately not the empty string: an absent value reads as "not set",
// which is the wrong claim about a var that is set.
func redactEnvValue(name, value string) string {
	if value != "" && credentialName(name) {
		return "(redacted)"
	}
	return value
}

