// The Dapr component type is the edge's nature — a source binding, the
// pub/sub bus — readable straight off spec.type. It rides on ResourceRef so
// a consumer can show "bindings.aws.s3" without decoding the manifest.
func TestScanCarriesTheDaprComponentType(t *testing.T) {
	root := t.TempDir()
	writeShowTree(t, root, "domains/orders/order-flow/order-flow-shared/base/binding.yaml", `apiVersion: dapr.io/v1alpha1
kind: Component
metadata:
  name: binding.order-source
spec:
  type: bindings.aws.s3
  metadata:
    - name: bucket
      value: orders
`)
	writeShowTree(t, root, "domains/orders/order-flow/order-flow-shared/base/cronjob.yaml", `apiVersion: batch/v1
kind: CronJob
metadata:
  name: sweeper
`)

	got, _ := scan(t, root, showCoord)
	byName := map[string]ResourceRef{}
	for _, r := range got.resources {
		byName[r.Name] = r
	}
	if byName["binding.order-source"].Type != "bindings.aws.s3" {
		t.Errorf("Component type = %q, want bindings.aws.s3", byName["binding.order-source"].Type)
	}
	if byName["sweeper"].Type != "" {
		t.Errorf("a CronJob has no type to report, got %q", byName["sweeper"].Type)
	}
	// The metadata values stay in the repository: a generic spec walk is one
	// careless manifest away from printing a credential.
	if strings.Contains(fmt.Sprint(got), "orders") {
		t.Error("metadata values must never leave the repository")
	}
}

// What an overlay sets is deployment configuration no source-derived
// topology can know: the namespace, the pinned image, the endpoints patched
// in per environment.
func TestScanInventoriesOverlays(t *testing.T) {
	root := t.TempDir()
	writeShowTree(t, root, "domains/orders/order-flow/order-flow-shared/overlays/prod/kustomization.yaml", `apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
namespace: prod-entrovia-integrations
resources:
  - ../../base
images:
  - name: harbor.intropy.io/app
    digest: sha256:f7550d1962fb77a314f7162c47b8fb8e87547f18083afb528fb00c9530a198e3
patches:
  - patch: |
      apiVersion: batch/v1
      kind: CronJob
      metadata:
        name: sweeper
      spec:
        jobTemplate:
          spec:
            template:
              spec:
                containers:
                  - name: app
                    env:
                      - name: OTEL_EXPORTER_OTLP_ENDPOINT
                        value: "http://alloy.services:4317"
                      - name: IdempotencySvcAppId
                        value: "iss-idempotency-service.services"
`)
	writeShowTree(t, root, "domains/orders/order-flow/order-flow-shared/overlays/nobody/kustomization.yaml",
		"apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\nresources:\n  - ../../base\n")

	// prod is the only declared environment; "nobody" is the half-onboarded
	// overlay show exists to surface.
	var stderr bytes.Buffer
	got := scanComponentManifests(root, showCoord, []string{"prod"}, &stderr)

	if len(got.overlays) != 2 {
		t.Fatalf("overlays = %v, want prod and the undeclared one", got.overlays)
	}
	prod, nobody := got.overlays[1], got.overlays[0]
	if prod.Name != "prod" || !prod.Declared {
		t.Errorf("prod = %+v, want declared", prod)
	}
	if prod.Namespace != "prod-entrovia-integrations" {
		t.Errorf("namespace = %q", prod.Namespace)
	}
	if len(prod.Images) != 1 || prod.Images[0].Digest == "" {
		t.Errorf("images = %+v, want the pinned digest", prod.Images)
	}
	wantEnv := []OverlayEnv{
		{Workload: "CronJob sweeper", Name: "OTEL_EXPORTER_OTLP_ENDPOINT", Value: "http://alloy.services:4317"},
		{Workload: "CronJob sweeper", Name: "IdempotencySvcAppId", Value: "iss-idempotency-service.services"},
	}
	if !reflect.DeepEqual(prod.Env, wantEnv) {
		t.Errorf("env =\n%#v\nwant\n%#v", prod.Env, wantEnv)
	}
	if nobody.Declared {
		t.Errorf("the undeclared overlay must be marked as such: %+v", nobody)
	}
}

// A literal credential in an overlay patch is masked before it can leave the
// repository. The marker is not the empty string: an absent value reads as
// "not set", which is the wrong claim about a var that is set.
func TestScanRedactsCredentialEnvValues(t *testing.T) {
	for _, tc := range []struct {
		name, value, want string
	}{
		{"OTEL_EXPORTER_OTLP_ENDPOINT", "http://alloy:4317", "http://alloy:4317"},
		{"SVC_API_TOKEN", "abc123", "(redacted)"},
		{"DB_PASSWORD", "hunter2", "(redacted)"},
		{"RABBITMQ_CONN", "amqp://x", "(redacted)"},
		{"ConnectionString", "Endpoint=sb://x", "(redacted)"},
		{"AWS_SECRET_ACCESS_KEY", "xyz", "(redacted)"},
	} {
		if got := redactEnvValue(tc.name, tc.value); got != tc.want {
			t.Errorf("redactEnvValue(%q) = %q, want %q", tc.name, got, tc.want)
		}
	}
}

