		Systems: []SystemInfo{{
			Domain: "orders", System: "order-flow",
			Components: []ComponentInfo{{
				Name:         "order-extractor",
				Kind:         "service",
				Environments: []string{"prod"},
				Overlays: []OverlayInfo{
					{Name: "prod", Declared: true, Namespace: "prod-entrovia-integrations",
						Images: []OverlayImage{{Name: "harbor/app", Digest: "sha256:f7550d1962fb77a314f7162c47b8fb8e87547f18083afb528fb00c9530a198e3"}},
						Env:    []OverlayEnv{{Workload: "CronJob sweeper", Name: "OTEL_EXPORTER_OTLP_ENDPOINT", Value: "http://alloy:4317"}}},
					{Name: "verify", Declared: false},
				},
			}},
		}},
	}
	if err := reportShow(output{Format: OutputPlain, Stdout: &stdout}, res); err != nil {
		t.Fatal(err)
	}
	out := stdout.String()
	for _, want := range []string{"prod: namespace prod-entrovia-integrations", "harbor/app@sha256:f7550d1962fb", "OTEL_EXPORTER_OTLP_ENDPOINT=http://alloy:4317", "verify: undeclared"} {
		if !strings.Contains(out, want) {
			t.Errorf("output should contain %q:\n%s", want, out)
		}
	}
}

