		}
	}
}

// gatherStrings flattens every string field of a scan record, so the leak
// check above inspects values the scanner produced and nothing else.
func gatherStrings(v any) []string {
	var out []string
	var walk func(rv reflect.Value)
	walk = func(rv reflect.Value) {
		switch rv.Kind() {
		case reflect.String:
			out = append(out, rv.String())
		case reflect.Slice, reflect.Array:
			for i := range rv.Len() {
				walk(rv.Index(i))
			}
		case reflect.Struct:
			for i := range rv.NumField() {
				walk(rv.Field(i))
			}
		}
	}
	walk(reflect.ValueOf(v))
	return out
}

