// is deployment configuration that lives only in this repository. And a
// literal credential patched in beside them must never leave it.
func TestShowInventoriesOverlayConfiguration(t *testing.T) {
	_, cacheRoot := newShowFixture(t)
	res, _ := showJSON(t, cacheRoot)

	extractor := componentByName(t, res, "order-extractor")
	byName := map[string]OverlayInfo{}
	for _, ov := range extractor.Overlays {
		byName[ov.Name] = ov
	}
	prod, ok := byName["prod"]
	if !ok || !prod.Declared {
		t.Fatalf("prod overlay missing or not declared: %+v", extractor.Overlays)
	}
	if prod.Namespace != "prod-integrations" {
		t.Errorf("namespace = %q", prod.Namespace)
	}
	if len(prod.Images) != 1 || prod.Images[0].Digest != "sha256:1111111111111111111111111111111111111111111111111111111111111111" {
		t.Errorf("images = %+v, want the pinned digest", prod.Images)
	}

	var token, otel *OverlayEnv
	for i := range prod.Env {
		switch prod.Env[i].Name {
		case "SVC_API_TOKEN":
			token = &prod.Env[i]
		case "OTEL_EXPORTER_OTLP_ENDPOINT":
			otel = &prod.Env[i]
		}
	}
	if otel == nil || otel.Value != "http://alloy.services:4317" {
		t.Errorf("the OTel endpoint should be reported: %+v", prod.Env)
	}
	if token == nil || token.Value != "(redacted)" {
		t.Errorf("a credential value must be redacted, got %+v", token)
	}
	if token != nil && token.Workload != "Deployment order-extractor" {
		t.Errorf("the env entry should name its workload: %+v", token)
	}

	// The shared component's undeclared overlay is marked as such.
	shared := componentByName(t, res, "order-flow-shared")
	for _, ov := range shared.Overlays {
		if ov.Name == "nobody" && ov.Declared {
			t.Errorf("the undeclared overlay must be marked as such: %+v", ov)
		}
	}
}

