export interface ResourceRef {
  apiVersion: string
  kind: string
  name: string
  /** Repository-relative file. */
  file: string
}

edits.newText:
export interface ResourceRef {
  apiVersion: string
  kind: string
  name: string
  /** The Dapr component type ("bindings.aws.s3", "pubsub.rabbitmq") for kind
   *  Component — the edge's nature, read off the one field the Dapr schema
   *  fixes at a known path. Absent for every other kind. */
  type?: string
  /** Repository-relative file. */
  file: string
}

/** One images[] entry from an overlay's kustomization. */
export interface OverlayImage {
  name: string
  digest?: string
  tag?: string
}

/** One literal env value an overlay patch sets on a workload. */
export interface OverlayEnv {
  /** The patched resource, as "kind name". */
  workload: string
  name: string
  /** The literal value, or "(redacted)": credentials never leave the repo. */
  value: string
}

/** What one overlay directory sets: deployment configuration no
 *  source-derived topology can know — a connector endpoint retargeted here
 *  never touches the code the topology is derived from. Present for every
 *  overlay that exists, declared in component.yaml or not. */
export interface OverlayInfo {
  name: string
  /** False marks the half-onboarded state: an overlay nobody declared. */
  declared: boolean
  namespace?: string
  images?: OverlayImage[]
  env?: OverlayEnv[]
  /** An unreadable kustomization.yaml; never fails the listing. */
  error?: string
}

