// OverlayLine renders what one overlay sets: the namespace, the pinned
// image, and the patched endpoints — deployment configuration that lives
// only in the GitOps repository. Undeclared overlays are marked, not hidden.
function OverlayLine({ overlay: ov }: { overlay: OverlayInfo }) {
  const parts: string[] = []
  if (!ov.declared) parts.push('undeclared')
  if (ov.namespace) parts.push(`namespace ${ov.namespace}`)
  for (const img of ov.images ?? []) {
    if (img.digest) parts.push(`${img.name}@${img.digest.slice(0, 19)}…`)
    else if (img.tag) parts.push(`${img.name}:${img.tag}`)
  }
  for (const env of ov.env ?? []) {
    parts.push(env.value === '(redacted)' ? `${env.name}=(redacted)` : `${env.name}=${env.value}`)
  }
  if (ov.error) parts.push(`error: ${ov.error}`)
  if (parts.length === 0) return null
  return (
    <div className={`gitops-overlay${ov.declared ? '' : ' undeclared'}`}>
      <span className="gitops-overlay-name">{ov.name}</span>
      <span className="gitops-overlay-detail">{parts.join(' · ')}</span>
    </div>
  )
}

